const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sakha region (approximate bounding box)
  const sakha = ee.Geometry.Rectangle([105, 62, 135, 76]); // lon/lat

  // 2. Load MODIS Burned Area product
  const burnedArea = ee.ImageCollection('MODIS/006/MCD64A1');

  // 3. Filter for 2015
  const burned2015 = burnedArea
    .filterDate('2015-01-01', '2015-12-31')
    .filterBounds(sakha)
    .select('BurnDate');

  // 4. Filter for 2021
  const burned2021 = burnedArea
    .filterDate('2021-01-01', '2021-12-31')
    .filterBounds(sakha)
    .select('BurnDate');

  // 5. Check data availability
  const size2015 = burned2015.size().getInfo();
  const size2021 = burned2021.size().getInfo();

  print(`2015 Images: ${size2015}, 2021 Images: ${size2021}`);

  if (size2015 === 0 || size2021 === 0) {
    print("C1: Empty Collection - no burned area data for one or both years");
    return;
  }

  // 6. Mosaic and calculate burned area for each year
  const mosaic2015 = burned2015.mosaic();
  const mosaic2021 = burned2021.mosaic();

  // 7. Count valid burned pixels (BurnDate > 0 means burned)
  const burnedPixels2015 = mosaic2015.gt(0).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  const burnedPixels2021 = mosaic2021.gt(0).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 500,
    maxPixels: 1e9
  }).get('BurnDate').getInfo();

  print(`2015 Burned Pixels: ${burnedPixels2015}, 2021 Burned Pixels: ${burnedPixels2021}`);

  // 8. Validate results
  if (burnedPixels2015 === null || burnedPixels2021 === null) {
    print("C3: Calculation Failure - null result");
    return;
  }

  if (burnedPixels2015 === 0 && burnedPixels2021 === 0) {
    print("C2: No Valid Pixels - no burned areas detected in either year");
    return;
  }

  // 9. Compare burned area
  const burnedArea2015 = burnedPixels2015 * 500 * 500 / 1e6; // Convert to km²
  const burnedArea2021 = burnedPixels2021 * 500 * 500 / 1e6;

  print(`2015 Burned Area: ${burnedArea2015.toFixed(0)} km²`);
  print(`2021 Burned Area: ${burnedArea2021.toFixed(0)} km²`);

  // 10. Final answer
  if (burnedArea2015 > burnedArea2021) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
